package com.codeguardian.service; import com.codeguardian.dto.PermissionDTO; import com.codeguardian.entity.Permission; import com.codeguardian.repository.PermissionRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.List; @Service @RequiredArgsConstructor public class PermissionService{private final PermissionRepository repo; public List<Permission> getAllPermissions(){return repo.findAll();} public List<PermissionDTO> getAllPermissionDTOs(){return repo.findAll().stream().map(p->PermissionDTO.builder().id(p.getId()).code(p.getCode()).name(p.getName()).description(p.getDescription()).resource(resource(p.getCode())).action(action(p.getCode())).build()).toList();} private String resource(String c){return switch(c){case "ADMIN"->"ALL";case "QUERY"->"TASK, REPORT";case "REVIEW"->"TASK";case "CONFIG"->"CONFIG";default->"";};} private String action(String c){return switch(c){case "ADMIN"->"ALL";case "QUERY"->"READ";case "REVIEW"->"CREATE, READ";case "CONFIG"->"READ, UPDATE";default->"";};}}
